class Tally:
    def __init__(self, replica_id: str = ""):
        self.replica_id = replica_id
        self._increments = 0
        self._decrements = 0

    def inc(self, amount: int = 1) -> None:
        if amount < 0:
            raise ValueError("Amount must be non-negative")
        self._increments += amount

    def increment(self, amount: int = 1) -> None:
        self.inc(amount)

    def dec(self, amount: int = 1) -> None:
        if amount < 0:
            raise ValueError("Amount must be non-negative")
        self._decrements += amount

    def decrement(self, amount: int = 1) -> None:
        self.dec(amount)

    def value(self) -> int:
        return self._increments - self._decrements

    def merge(self, other: "Tally") -> "Tally":
        result = Tally(self.replica_id)
        result._increments = self._increments + other._increments
        result._decrements = self._decrements + other._decrements
        return result

    def add(self, amount: int) -> None:
        if amount >= 0:
            self.inc(amount)
        else:
            self.dec(-amount)


# Functional / alternative API helpers if needed
def create_tally(replica_id: str = "") -> Tally:
    return Tally(replica_id)

__all__ = ["Tally", "create_tally"]

