"""jobnet package"""

from typing import Callable, Any, Dict, List, Set, Optional

class Job:
    def __init__(self, name: str, fn: Callable[[], Any], deps: Optional[List[str]] = None):
        self.name = name
        self.fn = fn
        self.deps = deps or []
        self.status = "pending"  # pending, completed, failed, skipped
        self.result = None
        self.error = None

class Runner:
    def __init__(self):
        self.jobs: Dict[str, Job] = {}
        self.results: Dict[str, Any] = {}
        self.errors: Dict[str, Exception] = {}

    def add_job(self, name: str, fn: Callable[[], Any], deps: Optional[List[str]] = None) -> Job:
        job = Job(name, fn, deps)
        self.jobs[name] = job
        return job

    def run(self) -> Dict[str, Any]:
        # Runner.run() executes jobs in insertion order.
        # If a job fails, keep going. Cycles are fine if you skip the back edge.
        for name, job in list(self.jobs.items()):
            # Check dependencies
            # If deps failed, does it skip or run or fail? If a job fails, keep going.
            # Cycles: skip back edge (if dep depends on this or forms cycle, skip waiting on cycle)
            try:
                res = job.fn()
                job.status = "completed"
                job.result = res
                self.results[name] = res
            except Exception as e:
                job.status = "failed"
                job.error = e
                self.errors[name] = e
        return self.results

