"""slotbook package for managing calendar slots and bookings."""

from __future__ import annotations
from dataclasses import dataclass
from datetime import datetime, timedelta, date, time
from typing import List, Optional, Union, Iterable, Iterator
import zoneinfo

UTC = zoneinfo.ZoneInfo("UTC")

def to_utc(dt: datetime) -> datetime:
    """Ensure naive datetime is treated as UTC, or convert timezone-aware datetime to UTC."""
    if dt.tzinfo is None:
        return dt.replace(tzinfo=UTC)
    return dt.astimezone(UTC)

def is_conflicting(start1: datetime, end1: datetime, start2: datetime, end2: datetime) -> bool:
    """Closed interval conflict check: [start, end].
    A booking ending at 10:00 conflicts with one starting at 10:00."""
    s1, e1 = to_utc(start1), to_utc(end1)
    s2, e2 = to_utc(start2), to_utc(end2)
    return not (e1 < s2 or s1 > e2)


def advance_weekly(dt: datetime, tz_name: Optional[str] = None) -> datetime:
    """Advance a datetime by 1 week, respecting timezone/DST if specified.
    If recurring weekly events land on a missing DST hour, push forward one hour."""
    if tz_name is None and dt.tzinfo is not None and dt.tzinfo != UTC:
        tz = dt.tzinfo
    elif tz_name:
        tz = zoneinfo.ZoneInfo(tz_name)
    else:
        # Naive or UTC
        return dt + timedelta(days=7)

    # In local time
    local_dt = dt.astimezone(tz)
    target_date = local_dt.date() + timedelta(days=7)
    target_time = local_dt.time()

    # Try constructing naive local datetime
    naive_local = datetime.combine(target_date, target_time)

    # Check DST / transition
    # When local time does not exist (missing hour in spring forward):
    # In zoneinfo, datetime.combine localized might map to either side or fold.
    # To check if it's in a gap:
    try_dt = naive_local.replace(tzinfo=tz)
    # Check if round-trip through UTC preserves the wall clock time
    rt = try_dt.astimezone(UTC).astimezone(tz)
    if rt.time() != target_time:
        # It fell into a gap / missing hour! Push forward 1 hour.
        naive_local = naive_local + timedelta(hours=1)
        try_dt = naive_local.replace(tzinfo=tz)

    return try_dt


@dataclass
class Booking:
    start: datetime
    end: datetime
    title: str = ""
    description: str = ""
    weekly: bool = False
    tz: Optional[str] = None
    id: Optional[Union[str, int]] = None

    def __post_init__(self):
        # We store start and end. If naive, they are UTC.
        if self.start > self.end:
            raise ValueError("start cannot be after end")

    @property
    def start_utc(self) -> datetime:
        return to_utc(self.start)

    @property
    def end_utc(self) -> datetime:
        return to_utc(self.end)

    def conflicts_with(self, other: Booking) -> bool:
        return is_conflicting(self.start, self.end, other.start, other.end)

    def occurrences(self, until: datetime, max_count: int = 1000) -> Iterator[Booking]:
        """Yield occurrences of this booking up to `until`."""
        curr_start = self.start
        curr_end = self.end
        duration = self.end - self.start
        until_utc = to_utc(until)

        count = 0
        while count < max_count:
            if to_utc(curr_start) > until_utc:
                break
            yield Booking(
                start=curr_start,
                end=curr_end,
                title=self.title,
                description=self.description,
                weekly=self.weekly,
                tz=self.tz,
                id=self.id
            )
            count += 1
            if not self.weekly:
                break
            # Advance
            if self.tz:
                curr_start = advance_weekly(curr_start, self.tz)
                curr_end = curr_start + duration
            else:
                curr_start = advance_weekly(curr_start)
                curr_end = curr_start + duration


class SlotBook:
    def __init__(self):
        self._bookings: List[Booking] = []

    @property
    def bookings(self) -> List[Booking]:
        return list(self._bookings)

    def add(self, *args, **kwargs) -> Booking:
        return self.book(*args, **kwargs)

    def book(
        self,
        start: Optional[datetime] = None,
        end: Optional[datetime] = None,
        booking: Optional[Booking] = None,
        title: str = "",
        description: str = "",
        weekly: bool = False,
        tz: Optional[str] = None,
        id: Optional[Union[str, int]] = None,
        **kwargs
    ) -> Booking:
        if booking is not None:
            b = booking
        elif start is not None and end is not None:
            b = Booking(
                start=start,
                end=end,
                title=title or kwargs.get("name", ""),
                description=description,
                weekly=weekly or kwargs.get("recurring", False),
                tz=tz or kwargs.get("timezone", None),
                id=id
            )
        else:
            raise ValueError("Must provide either a Booking object or start and end datetimes.")

        if not self.is_available(b.start, b.end):
            raise ValueError(f"Slot {b.start} to {b.end} conflicts with an existing booking")

        self._bookings.append(b)
        return b

    def is_available(self, start: datetime, end: datetime) -> bool:
        s_utc = to_utc(start)
        e_utc = to_utc(end)
        for b in self._bookings:
            if is_conflicting(s_utc, e_utc, b.start, b.end):
                return False
        return True

    def query(self, start: Optional[datetime] = None, end: Optional[datetime] = None) -> List[Booking]:
        if start is None and end is None:
            return list(self._bookings)
        s_utc = to_utc(start) if start else datetime.min.replace(tzinfo=UTC)
        e_utc = to_utc(end) if end else datetime.max.replace(tzinfo=UTC)
        return [b for b in self._bookings if is_conflicting(s_utc, e_utc, b.start, b.end)]

    def remove(self, booking: Booking) -> None:
        self._bookings.remove(booking)

    def cancel(self, booking: Booking) -> None:
        self.remove(booking)

    def __len__(self) -> int:
        return len(self._bookings)

    def __iter__(self):
        return iter(self._bookings)


# Convenience top level functions & exports
Booker = SlotBook
Schedule = SlotBook

