import time
from typing import Optional, Dict, Any

class Lease:
    def __init__(self, key: str, owner: str, timestamp: float, generation: int = 1):
        self.key = key
        self.owner = owner
        self.timestamp = timestamp
        self.generation = generation

    def is_expired(self, current_time: Optional[float] = None, ttl: Optional[float] = None) -> bool:
        if ttl is None:
            return False
        now = time.time() if current_time is None else current_time
        return now - self.timestamp > ttl

class HoldBook:
    def __init__(self):
        self._leases: Dict[str, Lease] = {}

    def acquire(self, key: str, owner: str, timestamp: Optional[float] = None) -> Lease:
        ts = time.time() if timestamp is None else timestamp
        current = self._leases.get(key)
        if current is None:
            lease = Lease(key=key, owner=owner, timestamp=ts, generation=1)
            self._leases[key] = lease
            return lease

        # Rule: newest timestamp wins
        if ts >= current.timestamp:
            new_gen = current.generation + 1
            lease = Lease(key=key, owner=owner, timestamp=ts, generation=new_gen)
            self._leases[key] = lease
            return lease
        else:
            return current

    def get(self, key: str) -> Optional[Lease]:
        return self._leases.get(key)

    def expire(self, key: str) -> None:
        if key in self._leases:
            del self._leases[key]

    def release(self, key: str, owner: Optional[str] = None) -> bool:
        current = self._leases.get(key)
        if current is None:
            return False
        if owner is not None and current.owner != owner:
            return False
        del self._leases[key]
        return True

__all__ = ["NONCE", "Lease", "HoldBook"]

